7	
8	// 本文件为“按费率项核对已受理报价”（ItemOutcomes）补充排序回归：
9	// 确认与拒绝混合列出时，必须按首次受理的完整实际时刻从早到晚排列，
10	// 同一瞬间再按请求标识的字符串顺序排列。所有时刻均写死并通过固定时钟注入，
11	// 结论可重复运行，不依赖执行当天的日期，也不需要等待真实时间流逝。
12	
13	// itemOutcomesSubSecondBase 是纳秒级排序回归的基准秒：
14	// 全部受理时刻都落在 2026-03-01 00:00:00 UTC 这一秒内。
15	var itemOutcomesSubSecondBase = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
16	
17	// newSubSecondAcceptanceBook 登记一条落在同一秒内的交接时间线：
18	//
19	//	seat-v1：单价 150 分，基准秒起生效，在第 100 毫秒被替代
20	//	seat-v2：单价 150 分，第 100 毫秒（含）起替代 seat-v1，持续有效
21	//
22	// 于是第 100 毫秒引用 v2 是正常确认，同一毫秒引用 v1 则以 version_expired
23	// 正常受理拒绝，方便构造“确认与拒绝混合、只相差一纳秒”的受理序列。
24	// now 是测试注入的固定时钟，登记时不读取时钟，受理时刻全部由测试显式拨表。
25	func newSubSecondAcceptanceBook(t *testing.T, now func() time.Time) *Book {
26		t.Helper()
27		b := NewBook(WithClock(now))
28		if err := b.RegisterVersion(RegisterRequest{
29			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
30			Start: itemOutcomesSubSecondBase,
31		}); err != nil {
32			t.Fatalf("register seat-v1: %v", err)
33		}
34		if err := b.RegisterVersion(RegisterRequest{
35			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 150,
36			Start:    itemOutcomesSubSecondBase.Add(100 * time.Millisecond),
37			Replaces: "seat-v1",
38		}); err != nil {
39			t.Fatalf("register seat-v2: %v", err)
40		}
41		return b
42	}
43	
44	// TestItemOutcomesSubsecondOrderingOneNanosecond 保护纳秒级先后：
45	// 同一秒内第 100 毫秒与第 100 毫秒再加一纳秒受理的两笔记录不能被当成同刻。
46	// 后一笔的请求标识在字符串顺序上更靠前（q-a… < q-z…），较早一笔仍必须先列出；
47	// 列表中确认与正常受理的拒绝混合排列，不能按确认状态分组，也不能排除拒绝。
48	func TestItemOutcomesSubsecondOrderingOneNanosecond(t *testing.T) {
49		// 固定时钟：报价前把时钟拨到写死的受理时刻，不等待任何真实时间。
50		var clock time.Time
51		setNow := func(at time.Time) { clock = at }
52		b := newSubSecondAcceptanceBook(t, func() time.Time { return clock })
53	
54		t100ms := itemOutcomesSubSecondBase.Add(100 * time.Millisecond)
55		t100msPlus1 := t100ms.Add(time.Nanosecond)
56		t100msPlus2 := t100ms.Add(2 * time.Nanosecond)
57	
58		// 测试前提：三个时刻确实落在同一秒内且依次只差一纳秒，否则本回归不成立。
59		if t100ms.Unix() != t100msPlus2.Unix() {
60			t.Fatalf("三笔受理时刻应落在同一秒内: %v / %v", t100ms, t100msPlus2)
61		}
62		if t100msPlus1.Sub(t100ms) != time.Nanosecond || t100msPlus2.Sub(t100msPlus1) != time.Nanosecond {
63			t.Fatalf("受理时刻间隔应为一纳秒: %v, %v", t100msPlus1.Sub(t100ms), t100msPlus2.Sub(t100msPlus1))
64		}
65	
66		// ① 最早（100.000000ms）：引用新版确认，故意给字符串顺序最靠后的标识。
67		setNow(t100ms)
68		first, err := b.Quote(QuoteRequest{
69			RequestID: "q-z-first-accepted", ItemID: "seat", VersionID: "seat-v2", Quantity: 4,
70		})
71		if err != nil || !first.Confirmed {
72			t.Fatalf("最早一笔应为确认: %v %+v", err, first)
73		}
74	
75		// ② 晚一纳秒（100.000001ms）：引用已失效旧版，被正常受理拒绝，
76		//    故意给字符串顺序最靠前的标识——时刻先后必须压过标识顺序。
77		setNow(t100msPlus1)
78		rejected, err := b.Quote(QuoteRequest{
79			RequestID: "q-a-second-accepted", ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
80		})
81		if err != nil {
82			t.Fatalf("晚一纳秒的拒绝应正常受理: %v", err)
83		}
84		if rejected.Confirmed || rejected.Reason != ReasonVersionExpired {
85			t.Fatalf("晚一纳秒引用旧版应为 version_expired 拒绝: %+v", rejected)
86		}
87	
88		// ③ 最晚（100.000002ms）：再次确认，标识字符串顺序居中。
89		setNow(t100msPlus2)
90		third, err := b.Quote(QuoteRequest{
91			RequestID: "q-m-third-accepted", ItemID: "seat", VersionID: "seat-v2", Quantity: 1,
92		})
93		if err != nil || !third.Confirmed {
94			t.Fatalf("最晚一笔应为确认: %v %+v", err, third)
95		}
96	
97		// 正确顺序只能由完整时刻推出：q-z、q-a、q-m；
98		// 纯请求标识顺序会是 q-a、q-m、q-z，按确认状态分组会是 q-z、q-m、q-a。
99		wantIDs := []string{"q-z-first-accepted", "q-a-second-accepted", "q-m-third-accepted"}
100	
101		// map 遍历顺序随机：重复列取多轮，每轮都必须严格一致，保证排序不依赖遍历运气。
102		var firstList []Outcome
103		for round := 0; round < 30; round++ {
104			got, err := b.ItemOutcomes("seat")
105			if err != nil {
106				t.Fatalf("round %d: %v", round, err)
107			}
108			if len(got) != 3 {
109				t.Fatalf("round %d: 确认与拒绝都必须列出，应有 3 条, got %d: %+v", round, len(got), got)
110			}
111			if ids := requestIDs(got); !equalStrings(ids, wantIDs) {
112				t.Fatalf("round %d: 纳秒级先后被打乱, want %v, got %v", round, wantIDs, ids)
113			}
114			if round == 0 {
115				firstList = got
116			}
117		}
118	
119		got := firstList
120	
121		// 排序后每条记录仍保留首次受理的完整字段：完整小数时刻、请求来源、
122		// 确认状态、金额或拒绝原因；两笔记录各自独立存在，不被合并。
123		earlier := got[0]
124		if earlier.Request.RequestID != "q-z-first-accepted" ||
125			earlier.Request.ItemID != "seat" || earlier.Request.VersionID != "seat-v2" ||
126			earlier.Request.Quantity != 4 || !earlier.Confirmed ||
127			earlier.UnitPrice != 150 || earlier.Total != 600 || earlier.Reason != ReasonNone {
128			t.Fatalf("150 分 × 数量 4 的确认必须保留 600 分与完整来源: %+v", earlier)
129		}
130		if !earlier.AcceptedAt.Equal(t100ms) || earlier.AcceptedAt.UnixNano() != t100ms.UnixNano() {
131			t.Fatalf("最早一笔的受理时刻小数部分被改写: got %v, want %v", earlier.AcceptedAt, t100ms)
132		}
133	
134		later := got[1]
135		if later.Request.RequestID != "q-a-second-accepted" ||
136			later.Request.ItemID != "seat" || later.Request.VersionID != "seat-v1" ||
137			later.Request.Quantity != 4 || later.Confirmed ||
138			later.Reason != ReasonVersionExpired || later.UnitPrice != 0 || later.Total != 0 {
139			t.Fatalf("version_expired 拒绝必须保留原因与零金额，不能变成免费确认价: %+v", later)
140		}
141		if !later.AcceptedAt.Equal(t100msPlus1) || later.AcceptedAt.UnixNano() != t100msPlus1.UnixNano() {
142			t.Fatalf("拒绝一笔的受理时刻小数部分被改写: got %v, want %v", later.AcceptedAt, t100msPlus1)
143		}
144	
145		// 相邻两条相差恰好一纳秒，且同在一个整秒内：小数部分没有被舍去后写回结果。
146		if gap := got[1].AcceptedAt.Sub(got[0].AcceptedAt); gap != time.Nanosecond {
147			t.Fatalf("前两条受理时刻间隔应为一纳秒, got %v", gap)
148		}
149		if gap := got[2].AcceptedAt.Sub(got[1].AcceptedAt); gap != time.Nanosecond {
150			t.Fatalf("后两条受理时刻间隔应为一纳秒, got %v", gap)
151		}
152		if got[0].AcceptedAt.Unix() != got[1].AcceptedAt.Unix() {
153			t.Fatalf("前两条应落在同一整秒内，仅小数部分不同")
154		}
155		if got[2].UnitPrice != 150 || got[2].Total != 150 {
156			t.Fatalf("第三笔确认金额异常: %+v", got[2])
157		}
158	
159		// 单笔查询与列表一致：排序逻辑不能影响已保存的首次受理内容。
160		if lookup, err := b.Lookup("q-z-first-accepted"); err != nil || lookup != first {
161			t.Fatalf("Lookup 最早一笔与首次结果不一致: %v %+v vs %+v", err, lookup, first)
162		}
163		if lookup, err := b.Lookup("q-a-second-accepted"); err != nil || lookup != rejected {
164			t.Fatalf("Lookup 拒绝一笔与首次结果不一致: %v %+v vs %+v", err, lookup, rejected)
165		}
166	}
167	
168	// TestItemOutcomesSameInstantDifferentZoneTieBreak 保护时区同刻判定：
169	// 2026-03-01 00:00:00.1 UTC 与 08:00:00.1 +08:00 是同一瞬间，
170	// 表示不同不能让列表失去同刻规则——同刻只按请求标识字符串顺序排列，
171	// 两笔记录都必须保留，小数部分也不能丢。
172	func TestItemOutcomesSameInstantDifferentZoneTieBreak(t *testing.T) {
173		var clock time.Time
174		b := NewBook(WithClock(func() time.Time { return clock }))
175		versionStart := time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC)
176		if err := b.RegisterVersion(RegisterRequest{
177			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150, Start: versionStart,
178		}); err != nil {
179			t.Fatal(err)
180		}
181	
182		east := time.FixedZone("UTC+8", 8*3600)
183		tUTC := time.Date(2026, 3, 1, 0, 0, 0, 100000000, time.UTC)
184		tEast := time.Date(2026, 3, 1, 8, 0, 0, 100000000, east)
185	
186		// 测试前提：两者确为同一瞬间，但时区表示与时间文本不同。
187		if !tUTC.Equal(tEast) || tUTC.UnixNano() != tEast.UnixNano() {
188			t.Fatalf("测试时间构造错误：%v 与 %v 应为同一瞬间", tUTC, tEast)
189		}
190		if tUTC.Format(time.RFC3339) == tEast.Format(time.RFC3339) {
191			t.Fatalf("测试时间构造错误：两者文本表示应不同")
192		}
193	
194		// 先提交 +08:00 表示且标识靠后的一笔，再提交 UTC 表示且标识靠前的一笔。
195		clock = tEast
196		eastOut, err := b.Quote(QuoteRequest{
197			RequestID: "q-z-east-repr", ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
198		})
199		if err != nil || !eastOut.Confirmed || eastOut.Total != 600 {
200			t.Fatalf("+08:00 表示的受理应正常确认: %v %+v", err, eastOut)
201		}
202		clock = tUTC
203		utcOut, err := b.Quote(QuoteRequest{
204			RequestID: "q-a-utc-repr", ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
205		})
206		if err != nil || !utcOut.Confirmed || utcOut.Total != 600 {
207			t.Fatalf("UTC 表示的受理应正常确认: %v %+v", err, utcOut)
208		}
209	
210		wantIDs := []string{"q-a-utc-repr", "q-z-east-repr"}
211		for round := 0; round < 30; round++ {
212			got, err := b.ItemOutcomes("seat")
213			if err != nil {
214				t.Fatalf("round %d: %v", round, err)
215			}
216			// 同刻两笔都必须存在，不能因时刻相等被合并。
217			if len(got) != 2 {
218				t.Fatalf("round %d: 同刻两笔必须各自保留, got %d: %+v", round, len(got), got)
219			}
220			if ids := requestIDs(got); !equalStrings(ids, wantIDs) {
221				t.Fatalf("round %d: 同刻应只按请求标识排序, want %v, got %v", round, wantIDs, ids)
222			}
223		}
224	
225		got, _ := b.ItemOutcomes("seat")
226		// 两条记录的完整受理时刻（含一亿纳秒小数）都原样保留，可按任一表示核对。
227		for _, o := range got {
228			if !o.AcceptedAt.Equal(tUTC) || o.AcceptedAt.UnixNano() != tUTC.UnixNano() {
229				t.Fatalf("同刻记录的完整受理时刻被改写: %+v", o)
230			}
231			if o.AcceptedAt.Nanosecond() != 100000000 {
232				t.Fatalf("受理时刻的小数部分被舍去: %v", o.AcceptedAt)
233			}
234			if o.Request.ItemID != "seat" || !o.Confirmed || o.UnitPrice != 150 || o.Total != 600 {
235				t.Fatalf("同刻记录必须保留请求来源与确认金额: %+v", o)
236			}
237		}
238	}
239	
240	// TestItemOutcomesOrdersByInstantAcrossDates 保护跨日期显示时仍按真实时刻排列：
241	// 日历日期、显示的小时数或时间文本都不能成为排序依据。
242	func TestItemOutcomesOrdersByInstantAcrossDates(t *testing.T) {
243		var clock time.Time
244		b := NewBook(WithClock(func() time.Time { return clock }))
245		if err := b.RegisterVersion(RegisterRequest{
246			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
247			Start: time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC),
248		}); err != nil {
249			t.Fatal(err)
250		}
251	
252		east := time.FixedZone("UTC+8", 8*3600)
253	
254		// 真实更早的一笔：+08:00 显示为 3 月 1 日 00:00（UTC 实为 2 月 28 日 16:00）。
255		earlier := time.Date(2026, 3, 1, 0, 0, 0, 0, east)
256		// 真实更晚的一笔：UTC 显示仍停留在 2 月 28 日 23:00（+08:00 实为 3 月 1 日 07:00）。
257		later := time.Date(2026, 2, 28, 23, 0, 0, 0, time.UTC)
258	
259		// 测试前提：真实先后与显示的日历日期相反——按日期文本排序会得到错误结论。
260		if !later.After(earlier) {
261			t.Fatalf("测试时间构造错误：%v 应晚于 %v", later, earlier)
262		}
263		if earlier.Format("2006-01-02") <= later.Format("2006-01-02") {
264			t.Fatalf("测试时间构造错误：较早一笔显示的日历日期应更晚, got %s vs %s",
265				earlier.Format("2006-01-02"), later.Format("2006-01-02"))
266		}
267	
268		// 先提交真实更晚（显示日期更早）的一笔，再提交真实更早（显示日期更晚）的一笔，
269		// 标识顺序也与真实先后相反，避免任何次级规则“碰巧”给出正确答案。
270		clock = later
271		laterOut, err := b.Quote(QuoteRequest{
272			RequestID: "q-ccc-later-instant", ItemID: "seat", VersionID: "seat-v1", Quantity: 1,
273		})
274		if err != nil || !laterOut.Confirmed {
275			t.Fatalf("真实更晚一笔受理失败: %v %+v", err, laterOut)
276		}
277		clock = earlier
278		earlierOut, err := b.Quote(QuoteRequest{
279			RequestID: "q-bbb-earlier-instant", ItemID: "seat", VersionID: "seat-v1", Quantity: 4,
280		})
281		if err != nil || !earlierOut.Confirmed || earlierOut.Total != 600 {
282			t.Fatalf("真实更早一笔受理失败: %v %+v", err, earlierOut)
283		}
284	
285		wantIDs := []string{"q-bbb-earlier-instant", "q-ccc-later-instant"}
286		for round := 0; round < 30; round++ {
287			got, err := b.ItemOutcomes("seat")
288			if err != nil {
289				t.Fatalf("round %d: %v", round, err)
290			}
291			if len(got) != 2 {
292				t.Fatalf("round %d: 应有 2 条记录, got %d: %+v", round, len(got), got)
293			}
294			if ids := requestIDs(got); !equalStrings(ids, wantIDs) {
295				t.Fatalf("round %d: 跨日期记录必须按真实时刻排列, want %v, got %v", round, wantIDs, ids)
296			}
297			if !got[0].AcceptedAt.Before(got[1].AcceptedAt) {
298				t.Fatalf("round %d: 列表顺序不满足实际时刻从早到晚: %v !< %v",
299					round, got[0].AcceptedAt, got[1].AcceptedAt)
300			}
301		}
302	
303		got, _ := b.ItemOutcomes("seat")
304		if !got[0].AcceptedAt.Equal(earlier) || got[0].Total != 600 {
305			t.Fatalf("较早一笔的完整时刻与金额必须保留: %+v", got[0])
306		}
307		if !got[1].AcceptedAt.Equal(later) || got[1].Total != 150 {
308			t.Fatalf("较晚一笔的完整时刻与金额必须保留: %+v", got[1])
309		}
310	}
311	
312	// TestItemOutcomesSameInstantAcrossDateBoundary 补一对跨日期的同刻记录：
313	// UTC 前一天晚上 == +08:00 次日清晨，日历日期不同也只能按请求标识排列。
314	func TestItemOutcomesSameInstantAcrossDateBoundary(t *testing.T) {
315		var clock time.Time
316		b := NewBook(WithClock(func() time.Time { return clock }))
317		if err := b.RegisterVersion(RegisterRequest{
318			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
319			Start: time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC),
320		}); err != nil {
321			t.Fatal(err)
322		}
323	
324		east := time.FixedZone("UTC+8", 8*3600)
325		nightUTC := time.Date(2026, 2, 28, 23, 59, 59, 100000000, time.UTC)
326		morningEast := time.Date(2026, 3, 1, 7, 59, 59, 100000000, east)
327		if !nightUTC.Equal(morningEast) {
328			t.Fatalf("测试时间构造错误：%v 与 %v 应为同一瞬间", nightUTC, morningEast)
329		}
330		if nightUTC.Format("2006-01-02") == morningEast.Format("2006-01-02") {
331			t.Fatalf("测试时间构造错误：两者显示的日历日期应不同")
332		}
333	
334		clock = nightUTC
335		if _, err := b.Quote(QuoteRequest{
336			RequestID: "q-z-utc-night", ItemID: "seat", VersionID: "seat-v1", Quantity: 1,
337		}); err != nil {
338			t.Fatal(err)
339		}
340		clock = morningEast
341		if _, err := b.Quote(QuoteRequest{
342			RequestID: "q-a-east-morning", ItemID: "seat", VersionID: "seat-v1", Quantity: 1,
343		}); err != nil {
344			t.Fatal(err)
345		}
346	
347		wantIDs := []string{"q-a-east-morning", "q-z-utc-night"}
348		for round := 0; round < 30; round++ {
349			got, err := b.ItemOutcomes("seat")
350			if err != nil {
351				t.Fatalf("round %d: %v", round, err)
352			}
353			if ids := requestIDs(got); !equalStrings(ids, wantIDs) {
354				t.Fatalf("round %d: 跨日期同刻只能按请求标识排列, want %v, got %v",
355					round, wantIDs, ids)
356			}
357			if !got[0].AcceptedAt.Equal(got[1].AcceptedAt) {
358				t.Fatalf("round %d: 两条记录应判定为同刻", round)
359			}
360		}
361	}
362	
363	func equalStrings(a, b []string) bool {
364		if len(a) != len(b) {
365			return false
366		}
367		for i := range a {
368			if a[i] != b[i] {
369				return false
370			}
371		}
372		return true
373	}
