77		}
78		if v1.Replaces != "" || v1.SupersededBy != "" {
79			t.Fatalf("v1 不应存在替代关系: Replaces=%q SupersededBy=%q",
80				v1.Replaces, v1.SupersededBy)
81		}
82	
83		if v3.UnitPrice != 200 || !v3.Start.Equal(gfV3Start) || !v3.EffectiveStart.Equal(gfV3Start) {
