99	// 补登记前的基线：尽管 v3 先于 v1 登记，列表仍按生效时刻列为 v1、v3，
100	// 且 3 月 15 日落在两版之间的空档，按时刻查询返回 ErrNoEffectiveVersion。
101	func TestGapBaseOrderingByEffectiveTimeAndGapHasNoVersion(t *testing.T) {
