146			t.Fatalf("v1 登记信息异常: %+v", v1)
147		}
148		if v1.End == nil || !v1.End.Equal(gfV1End) ||
149			v1.EffectiveEnd == nil || !v1.EffectiveEnd.Equal(gfV1End) {
