151		}
152	
153		// v2 登记的起止时刻就是它的实际有效区间 [03-10, 03-20)。
154		if v2.UnitPrice != 180 {
155			t.Fatalf("v2 单价应为 180, got %d", v2.UnitPrice)
156		}
157		if !v2.Start.Equal(gfV2Start) || v2.End == nil || !v2.End.Equal(gfV2End) ||
158			v2.EffectiveEnd == nil || !v2.EffectiveEnd.Equal(gfV2End) {
159			t.Fatalf("v2 实际有效区间应为 [03-10, 03-20): 起点=%v 登记结束=%v 实际结束=%v",
160				v2.Start, v2.End, v2.EffectiveEnd)
161		}
162	
