169		}
170	
171		// 按时刻查询：开始时刻含、结束时刻不含；端点相接处选右侧版本，
172		// 端点前一纳秒仍选左侧版本；空档内部现在归 v2；v3 在 3 月 20 日后持续生效。
173		cases := []struct {
