182			{"v3 起点前一纳秒仍归 v2", gfV3Start.Add(-time.Nanosecond), "seat-v2", 180},
183			{"v3 起点（含）归 v3", gfV3Start, "seat-v3", 200},
184			{"3 月 20 日之后 v3 持续有效", time.Date(2026, 4, 1, 0, 0, 0, 0, time.UTC), "seat-v3", 200},
185		}
186		for _, c := range cases {
187			t.Run(c.name, func(t *testing.T) {
188				got, err := b.EffectiveVersionAt("seat", c.at)
189				if err != nil {
