191				}
192				if got.VersionID != c.versionID || got.UnitPrice != c.unitPrice {
193					t.Fatalf("%s: 查询 %s 得到 %s/%d, want %s/%d",
194						c.name, c.at.Format(time.RFC3339Nano),
195						got.VersionID, got.UnitPrice, c.versionID, c.unitPrice)
196				}
197			})
198		}
199	}
200	
201	// 补登记两侧的重叠都必须沿用既有的 ErrOverlap：起点早一纳秒会侵入 v1 的
202	// 实际有效期，终点晚一纳秒会侵入持续有效的 v3。失败整次回滚，原两版的
203	// 单价、起止时刻与关系不变，空档查询仍返回 ErrNoEffectiveVersion；
204	// 修正为恰好填满空档后，同一 v2 标识仍能登记成功（失败不占用标识）。
205	func TestFillGapOverlapOneNanosecondEitherSideRejectedThenSameIDSucceeds(t *testing.T) {
206		cases := []struct {
207			name  string
208			start time.Time
209			end   time.Time
210		}{
211			{"起点比 3 月 10 日早一纳秒", gfV2Start.Add(-time.Nanosecond), gfV2End},
212			{"终点比 3 月 20 日晚一纳秒", gfV2Start, gfV2End.Add(time.Nanosecond)},
213		}
214		for _, c := range cases {
215			t.Run(c.name, func(t *testing.T) {
216				b := newGapBook(t)
217	
218				end := c.end
219				err := b.RegisterVersion(RegisterRequest{
220					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
221					Start: c.start, End: &end,
222				})
223				if !errors.Is(err, ErrOverlap) {
224					t.Fatalf("%s 应返回 ErrOverlap, got %v", c.name, err)
225				}
226	
227				// 失败整次回滚：仍只有 v1、v3，单价、起止与关系不变，空档仍在。
228				assertGapBaseUnchanged(t, b)
229	
230				// 修正为恰好填满空档，沿用同一版本标识 seat-v2 登记成功。
231				fixedEnd := gfV2End
232				if err := b.RegisterVersion(RegisterRequest{
233					ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
234					Start: gfV2Start, End: &fixedEnd,
235				}); err != nil {
236					t.Fatalf("失败登记不应占用标识，恰好填满空档后沿用 seat-v2 应成功: %v", err)
237				}
238	
239				views, err := b.ItemVersions("seat")
240				if err != nil {
241					t.Fatal(err)
242				}
243				if len(views) != 3 {
244					t.Fatalf("修正后应有三个版本, got %d: %+v", len(views), views)
245				}
246				if views[0].VersionID != "seat-v1" || views[1].VersionID != "seat-v2" ||
247					views[2].VersionID != "seat-v3" {
248					t.Fatalf("修正后版本顺序异常: %q、%q、%q",
249						views[0].VersionID, views[1].VersionID, views[2].VersionID)
250				}
251	
252				// 原空档现在归 v2，两个交接点的归属也符合半开区间约定。
253				got, err := b.EffectiveVersionAt("seat", gfGapAt)
254				if err != nil {
255					t.Fatalf("修正后空档查询应成功: %v", err)
256				}
257				if got.VersionID != "seat-v2" || got.UnitPrice != 180 {
258					t.Fatalf("空档应归 v2/180, got %s/%d", got.VersionID, got.UnitPrice)
259				}
260				left, err := b.EffectiveVersionAt("seat", gfV2Start.Add(-time.Nanosecond))
261				if err != nil || left.VersionID != "seat-v1" {
262					t.Fatalf("v2 起点前一纳秒应仍归 v1, got %+v err=%v", left, err)
263				}
264				atV2Start, err := b.EffectiveVersionAt("seat", gfV2Start)
265				if err != nil || atV2Start.VersionID != "seat-v2" {
266					t.Fatalf("3 月 10 日零点应归 v2, got %+v err=%v", atV2Start, err)
267				}
268				beforeV3, err := b.EffectiveVersionAt("seat", gfV3Start.Add(-time.Nanosecond))
269				if err != nil || beforeV3.VersionID != "seat-v2" {
270					t.Fatalf("3 月 20 日零点前一纳秒应仍归 v2, got %+v err=%v", beforeV3, err)
271				}
272				atV3Start, err := b.EffectiveVersionAt("seat", gfV3Start)
273				if err != nil || atV3Start.VersionID != "seat-v3" {
274					t.Fatalf("3 月 20 日零点应归 v3, got %+v err=%v", atV3Start, err)
275				}
276			})
277		}
278	}
